 "content": "def transform(grid):
    # Preserve each multi-cell same-color object; remove isolated contaminants.
    h, w = len(grid), len(grid[0])
    out = [[3] * w for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (3, 0, 4, 6) or (r, c) in seen:
                continue
            stack = [(r, c)]; comp = []
            seen.add((r, c))
            while stack:
                y, x = stack.pop(); comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if len(comp) > 1:
                for y, x in comp: out[y][x] = color
    return out
"
